contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 value) public {
        require(to != address(0));
        require(!c.frozenAccount(address(this)));
        require(!c.frozenAccount(to));
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 toBefore = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        require(value > senderBefore);
        bool reverted;
        c.transfer(to, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted
            && c.balanceOf(address(this)) == senderBefore
            && c.balanceOf(to) == toBefore
            && c.totalSupply() == supplyBefore
        );
    }
    receive() external payable {}
}

